// Loads infra/local/.env.local (generated by `pnpm local:init`) into process.env without overriding real env vars.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export function loadLocalEnv(root: string): void {
  const file = join(root, "infra", "local", ".env.local");
  if (!existsSync(file)) return;
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line || line.startsWith("#")) continue;
    const i = line.indexOf("=");
    if (i > 0 && process.env[line.slice(0, i)] === undefined) process.env[line.slice(0, i)] = line.slice(i + 1);
  }
}
